from pydantic import BaseModel

class Step(BaseModel):
    action: str            # e.g. "search"
    args: dict             # e.g. {"query": "OpenAI Agents SDK"}

class Plan(BaseModel):
    steps: list[Step]

# a typed plan can be logged, approved, or edited before execution

def execute(plan, goal):
    done = []
    while plan.steps:
        step = plan.steps.pop(0)
        try:
            done.append(executor(step))
        except StepFailed as e:
            # revise the REMAINING steps given what happened
            plan = replanner(goal, done, error=str(e))
    return done

