def planner(goal):
    # one call maps the goal to ordered, concrete steps
    return [
        {"action": "fetch", "args": {"q": goal}},
        {"action": "summarize", "args": {}},
    ]

TOOLS = {
    "fetch": lambda q: f"raw docs about '{q}'",
    "summarize": lambda text: f"summary of: {text}",
}

def execute(plan):
    last = None
    for step in plan:
        if step["action"] == "summarize":
            last = TOOLS["summarize"](last)      # uses prior result
        else:
            last = TOOLS[step["action"]](**step["args"])
    return last

plan = planner("quantum computing")   # planned ONCE
print(execute(plan))

