    pass

def run(goal, planner, executor, replanner, max_iters=10):
    plan = planner(goal)          # plan ONCE
    results = []
    attempts = 0
    while plan:
        if attempts >= max_iters:
            raise RuntimeError("budget exceeded")
        step = plan.pop(0)
        attempts += 1
        try:
            results.append(executor(step, results))     # execute in order
        except StepFailed as e:
            # revise REMAINING steps; keep results gathered so far
            plan = replanner(goal, results, str(e))
    return results

