from typing import Callable

class StepFailed(Exception):
    pass

def drive(goal: str,
          planner: Callable,
          executor: Callable,
          replanner: Callable,
          max_iters: int = 10) -> list:
    plan = planner(goal)              # plan ONCE
    results: list = []
    attempts = 0
    while plan:
        if attempts >= max_iters:
            raise RuntimeError("budget exceeded")
        step = plan.pop(0)
        attempts += 1
        try:
            results.append(executor(step, results))   # prior results flow forward
        except StepFailed as e:
            plan = replanner(goal, results, str(e))    # revise remaining steps
    return results

if __name__ == "__main__":
    def planner(g):
        return [{"a": "read"}, {"a": "boom"}, {"a": "write"}]
    def executor(step, results):
        if step["a"] == "boom":
            raise StepFailed("tool down")
        return step["a"]
    def replanner(g, results, err):
        return [{"a": "retry"}, {"a": "write"}]
    print(drive("demo", planner, executor, replanner))
